#include "syspulse/native/task_view.hpp"
#include <cstdlib>
#include <iostream>
using namespace syspulse::native;
unsigned count=0;void check(bool ok,const char* name){++count;if(!ok){std::cerr<<name<<'\n';std::exit(1);}}
int main(){Inspection a,b;a.processAvailable=b.processAvailable=true;Process p{42,1,"Web Browser",'S',100,10,256},q{20,1,"Editor",'S',100,20,512};a.processes={p,q};p.cpuTicks=300;q.cpuTicks=150;b.processes={p,q};auto v=buildTaskView(a,b,2,100,4096);check(v.rows.size()==2&&!v.partial,"two valid rows");check(v.rows[0].cpuPercent==100&&v.rows[1].cpuPercent==25,"percent one CPU");check(v.rows[1].rssBytes==2097152,"RSS bytes");check(filterTasks(v,"browser",TaskSort::Pid).size()==1,"case-insensitive filter");check(filterTasks(v,"42",TaskSort::Pid)[0].process.pid==42,"PID search");check(filterTasks(v,"",TaskSort::Cpu)[0].process.pid==42,"CPU sort");check(filterTasks(v,"",TaskSort::Memory)[0].process.pid==20,"RSS sort");check(filterTasks(v,"",TaskSort::Name)[0].process.pid==20,"name sort");check(filterTasks(v,"",TaskSort::Pid)[0].process.pid==20,"PID sort");check(retainTaskSelection(v,p).has_value(),"identity kept");p.startTicks++;b.processes[0]=p;v=buildTaskView(a,b,2,100,4096);check(!v.rows[0].cpuPercent,"PID reuse excludes rate");check(!retainTaskSelection(v,a.processes[0]),"PID reuse clears selection");b.processes[0].rssPages=UINT64_MAX;check(!buildTaskView(a,b,2,100,4096).rows[0].rssBytes,"RSS overflow");check(!buildTaskView(a,b,31,100,4096).rows[1].cpuPercent,"stale rate");check(!buildTaskView(a,b,2,0,0).rows[1].cpuPercent,"unknown units");b.processTruncated=true;check(buildTaskView(a,b,2,100,4096).partial,"partial source");b.processes.push_back(p);check(buildTaskView(a,b,2,100,4096).rows.empty(),"duplicate PID refused");std::cout<<count<<" task view checks passed\n";}
